Heatmap_CellTypes <- function({{{Seurat_Object}}}, {{{Sample_Names_Table}}},{{{Metadata_Table}}}) {
    # image: png

    ## --------- ##
    ## Libraries ##
    ## --------- ##

    library(nidapFunctions)
    nidapLoadPackages(c("SCWorkflow","dplyr","Seurat"))

    ## -------------------------------- ##
    ## User-Defined Template Parameters ##
    ## -------------------------------- ##

    #Primary Inputs:
    seurat_object <- {{{Seurat_Object}}}
    metadata_table <- {{{Metadata_Table}}}
    sample_names <- {{{Sample_Names}}}

    #Basic Paramters:
    transcripts = {{{Transcripts}}}
    proteins = {{{Proteins}}}

    #Annotation Parameters:
    metadata_to_plot <- {{{Metadata_to_Plot}}}
    add_gene_or_protein_annotation_tracks <- {{{Add_Gene_or_Protein_Annotation_Tracks}}}
    rna_annotations = {{{RNA_Annotations}}}
    protein_annotations = {{{Protein_Annotations}}}
    arrange_by_metadata_annotations <- {{{Arrange_by_Metadata_Annotations}}}

    #Visualization Parameters:
    plot_title <- "{{{Plot_Title}}}"
    heatmap_color <- "{{{Heatmap_Color}}}" 
    set_seed_for_colors <- {{{Set_Seed_for_Colors}}}
    row_height <- {{{Row_Height}}} 
    add_row_names <- {{{Add_Row_Names}}}
    row_font_size <- {{{Row_Font_Size}}} 
    order_heatmap_rows <- {{{Order_Heatmap_Rows}}}
    row_order = {{{Row_Order}}}  
    add_column_names <- {{{Add_Column_Names}}}
    column_font_size <- {{{Column_Font_Size}}} 
    legend_font_size <- {{{Legend_Font_Size}}}

    #Advanced Parameters: 
    scale_data <- {{{Scale_Data_by_Rows}}}
    trim_outliers <- {{{Trim_Outliers}}}
    trim_outliers_percentage <- {{{Trim_Outliers_Percentage}}}
    seurat_object_filename <- "{{{Seurat_Object_Filename}}}"


    ## -------------------------------- ##
    ## Parameter Misspecifation Errors  ##
    ## -------------------------------- ##

    if(add_gene_or_protein_annotation_tracks == FALSE & (!is.null(protein_annotations) | !is.null(rna_annotations))) {
       stop("Error: You should choose to add gene or protein annotation tracks if you add protein or rna annotations")
    }

    if(is.null(metadata_to_plot)){
        stop("Error: You should choose at least one annotation track under metadata_to_plot")
    }

    ## -------------------------------- ##
    ## Functions                        ##
    ## -------------------------------- ##

    ## --------------- ##
    ## Main Code Block ##
    ## --------------- ##

    path <- nidapGetPath(seurat_object,seurat_object_filename)
    so <- readRDS(path)

print(so%>%Cells%>%length)
if(so%>%Cells%>%length>15000){
    stop('Too many Cells Selected (>15,000) to render Figure. Consider Filtering before creating Heatmap')
}


    ## Function changes here:
    library(dplyr)
    if("orig.ident" %in% colnames(so@meta.data)){
        print("orig.ident found in metadata")
        } else if ("orig_ident" %in% colnames(so@meta.data)){
            so@meta.data=dplyr::rename(so@meta.data, orig.ident=orig_ident)
        } else {
            print("orig.ident or orig_ident not found")
        }


    results <- heatmapSC(object = so,
                      sample.names = sample_names,
                      metadata = metadata_to_plot,
                      transcripts = transcripts,
                      proteins = proteins,
                      heatmap.color = heatmap_color,
                      plot.title = plot_title,
                      add.gene.or.protein = add_gene_or_protein_annotation_tracks,
                      protein.annotations = protein_annotations,
                      rna.annotations = rna_annotations,
                      arrange.by.metadata = arrange_by_metadata_annotations,
                      add.row.names = add_row_names,
                      add.column.names = add_column_names,
                      row.font = row_font_size,
                      col.font = column_font_size,
                      legend.font = legend_font_size,
                      row.height = row_height,
                      set.seed = set_seed_for_colors,
                      scale.data = scale_data,
                      trim.outliers = trim_outliers,
                      trim.outliers.percentage = trim_outliers_percentage,
                      order.heatmap.rows = order_heatmap_rows,
                      row.order = row_order) 

    print(results$plot)
    return(results$data)

}

